/*!40000 ALTER TABLE `leave_types` DISABLE KEYS */;
INSERT INTO `leave_types` VALUES (1,'VL','Vacation Leave',1,1,1,'2026-06-08 12:15:54','2026-06-15 00:40:55',1,'VL',NULL,5,'Sec. 51, Rule XVI, Omnibus Rules Implementing E.O. No. 292','File five days in advance whenever possible.','[\"Indicate whether leave is within the Philippines or abroad.\", \"Secure travel authority and clearance from money/work accountabilities when applicable.\"]','[\"location\", \"commutation\"]'),(2,'SL','Sick Leave',1,1,3,'2026-06-08 12:15:54','2026-06-15 00:40:55',1,'SL',NULL,NULL,'Sec. 43, Rule XVI, Omnibus Rules Implementing E.O. No. 292','File immediately upon return. If filed in advance or exceeding five days, attach medical certificate or affidavit if no consultation was availed of.','[\"Medical certificate if filed in advance or exceeding five days.\", \"Applicant affidavit if medical consultation was not availed of.\"]','[\"sick\", \"commutation\"]'),(3,'FL','Mandatory/Forced Leave',1,1,2,'2026-06-08 12:15:54','2026-06-15 00:40:55',1,'VL',5.000,NULL,'Sec. 25, Rule XVI, Omnibus Rules Implementing E.O. No. 292','Annual five-day vacation leave is forfeited if not taken during the year unless cancelled due to exigency of service.','[\"One day or more Vacation Leave may count toward mandatory/forced leave compliance, subject to rules.\"]','[\"commutation\"]'),(4,'SPL','Special Privilege Leave',1,1,6,'2026-06-08 12:15:54','2026-06-15 00:40:55',0,NULL,3.000,7,'Sec. 21, Rule XVI, Omnibus Rules Implementing E.O. No. 292','File/approve at least one week before availment, except emergency cases.','[\"Indicate whether leave is within the Philippines or abroad.\", \"Secure travel authority and clearance from money/work accountabilities when applicable.\"]','[\"location\", \"commutation\"]'),(5,'ML','Maternity Leave',1,1,4,'2026-06-08 12:15:54','2026-06-15 00:40:55',0,NULL,105.000,NULL,'R.A. No. 11210 / IRR issued by CSC, DOLE and SSS','105 days, with proof of pregnancy and CS Form No. 6a if needed.','[\"Proof of pregnancy, such as ultrasound or doctor\'s certificate on expected delivery date.\", \"Accomplished Notice of Allocation of Maternity Leave Credits (CS Form No. 6a), if needed.\"]','[\"commutation\"]'),(6,'PL','Paternity Leave',1,1,5,'2026-06-08 12:15:54','2026-06-15 00:40:55',0,NULL,7.000,NULL,'R.A. No. 8187 / CSC MC No. 71, s. 1998, as amended','Seven days with proof of child\'s delivery and marriage contract.','[\"Proof of child\'s delivery, such as birth certificate or medical certificate.\", \"Marriage contract.\"]','[\"commutation\"]'),(7,'SP','Solo Parent Leave',1,1,7,'2026-06-08 12:15:54','2026-06-15 00:40:55',0,NULL,7.000,5,'RA No. 8972 / CSC MC No. 8, s. 2004','File in advance or whenever possible five days before leave.','[\"Updated Solo Parent Identification Card.\"]','[\"commutation\"]'),(8,'LWOP','Leave Without Pay',0,1,99,'2026-06-08 12:15:54','2026-06-15 00:40:55',0,NULL,NULL,NULL,'','Internal unpaid leave tracking type.','[]','[\"commutation\"]'),(488,'STUDY','Study Leave',1,1,8,'2026-06-15 00:40:55','2026-06-15 00:40:55',0,NULL,132.000,NULL,'Sec. 68, Rule XVI, Omnibus Rules Implementing E.O. No. 292','Up to six months, subject to agency internal requirements and contract.','[\"Agency internal requirements, if any.\", \"Contract between agency head or authorized representative and employee.\"]','[\"study\", \"commutation\"]'),(489,'VAWC','10-Day VAWC Leave',1,1,9,'2026-06-15 00:40:55','2026-06-15 00:40:55',0,NULL,10.000,NULL,'RA No. 9262 / CSC MC No. 15, s. 2005','File in advance or immediately upon return.','[\"Barangay Protection Order, Temporary/Permanent Protection Order, filing certification, or police report with medical certificate as allowed.\"]','[\"commutation\"]'),(490,'REHAB','Rehabilitation Privilege',1,1,10,'2026-06-15 00:40:55','2026-06-15 00:40:55',0,NULL,132.000,7,'Sec. 55, Rule XVI, Omnibus Rules Implementing E.O. No. 292','Apply within one week from accident except when a longer period is warranted.','[\"Letter request supported by relevant reports, such as police report if any.\", \"Medical certificate on injuries, treatment, and need for rest, recuperation, and rehabilitation.\", \"Government physician concurrence if attending physician is private, especially on duration.\"]','[\"commutation\"]'),(491,'SLBW','Special Leave Benefits for Women',1,1,11,'2026-06-15 00:40:55','2026-06-15 00:40:55',0,NULL,44.000,5,'RA No. 9710 / CSC MC No. 25, s. 2010','May be filed at least five days before gynecological surgery; emergency cases are filed upon return with agency notification during confinement.','[\"Medical certificate and clinical summary from proper medical authorities.\", \"Histopathological report.\", \"Operative technique used, surgery duration, peri-operative period, and estimated recuperation period.\"]','[\"women\", \"commutation\"]'),(492,'CALAMITY','Special Emergency (Calamity) Leave',1,1,12,'2026-06-15 00:40:55','2026-06-15 00:40:55',0,NULL,5.000,NULL,'CSC MC No. 2, s. 2012, as amended','Maximum of five straight working days or staggered basis within thirty days from actual calamity/disaster; once per year.','[\"Verification of residence based on latest records.\", \"Verification that residence is covered by calamity area declaration.\", \"Other proofs as necessary.\"]','[\"commutation\"]'),(493,'ADOPTION','Adoption Leave',1,1,13,'2026-06-15 00:40:55','2026-06-15 00:40:55',0,NULL,NULL,NULL,'R.A. No. 8552','File with authenticated Pre-Adoptive Placement Authority issued by DSWD.','[\"Authenticated Pre-Adoptive Placement Authority issued by DSWD.\"]','[\"commutation\"]'),(494,'MONETIZATION','Monetization of Leave Credits',1,1,14,'2026-06-15 00:40:55','2026-06-15 00:40:55',1,'VL_SL',NULL,NULL,'','Application for monetization of 50% or more of accumulated leave credits requires a letter request stating valid and justifiable reasons.','[\"Letter request to the head of agency stating valid and justifiable reasons when monetizing 50% or more.\"]','[\"otherPurpose\"]'),(495,'TERMINAL','Terminal Leave',1,1,15,'2026-06-15 00:40:55','2026-06-15 00:40:55',1,'VL_SL',NULL,NULL,'','Requires proof of resignation, retirement, or separation from service.','[\"Proof of resignation, retirement, or separation from service.\", \"Clearance from money, property, and work-related accountabilities.\"]','[\"otherPurpose\"]'),(496,'OTHERS','Others',1,1,16,'2026-06-15 00:40:55','2026-06-15 00:40:55',0,NULL,NULL,NULL,'','Use only when the leave purpose does not match the standard CS Form No. 6 options.','[\"Specify the leave purpose and attach supporting documents required by HR.\"]','[\"otherPurpose\", \"commutation\"]');
/*!40000 ALTER TABLE `leave_types` ENABLE KEYS */;
